```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "TBox modelling securities, debt, equity, hybrid and derivative financial instruments, funds, and basic accounting classification, built from a corpus on securities." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled; per IAS 32, any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset. Also described as a financial contract entitling the holder to investment returns, secured by a contract enforceable by law. The legal definition varies by jurisdiction: some jurisdictions (e.g. UK FCA Handbook) restrict 'security' to equities, debentures, government/public securities, warrants and similar instruments, while the US treats any tradable financial asset, including derivatives, as a security. This ontology follows the cash-instrument/derivative-instrument split (see fis:CashInstrument, fis:Derivative) as the primary structural distinction, noting the broader US classification here as a documented conflict." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "A financial instrument whose value is determined directly by the markets; includes securities (readily transferable) and instruments such as loans and deposits, where both borrower and lender must agree to a transfer." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" ;
  rdfs:comment "A contract whose value is derived from the performance of an underlying item (a commodity, financial instrument, index, currency, interest rate, or event). Has an underlier, a future act, a price, and a future date. Note: the US SEC broad classification groups derivatives as one of three categories of 'security' (debt, equity, derivatives); this ontology instead treats Security and Derivative as disjoint subclasses of FinancialInstrument, following the cash-vs-derivative instrument split, and records the alternative classification here." .

fis:Loan a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "loan" ;
  rdfs:comment "A cash instrument such as a loan, not readily transferable without agreement of both borrower and lender; hence not a security." .

fis:Deposit a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "deposit" .

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security, fis:CashInstrument ;
  rdfs:label "debt security" ;
  rdfs:comment "A tradable financial asset under which the holder is entitled to payment of principal and interest and other contractual rights; may be called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security, fis:CashInstrument ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; a negotiable financial instrument representing ownership of a stake in a corporation. Not entitled to any fixed payment; shares in the residual interest of the issuer." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "A security combining some of the characteristics of both debt and equity securities (e.g. preference shares, convertible bonds)." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

#################################################################
# ISSUER / INVESTOR
#################################################################

fis:Issuer a owl:Class ;
  rdfs:label "issuer" ;
  rdfs:comment "The company or other entity issuing the security; the debtor on a bond." .

fis:Government a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "government" .
fis:MunicipalAuthority a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "municipal authority" .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "supranational organization" .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "corporation" .

owl:AllDisjointClasses [ owl:members ( fis:Government fis:MunicipalAuthority fis:SupranationalOrganization fis:Corporation ) ] .

fis:Investor a owl:Class ;
  rdfs:label "investor" ;
  rdfs:comment "A holder of a security; may be retail (a member of the public investing personally) or institutional (acting on own account or behalf of clients)." .

fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor .
owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

fis:Shareholder a owl:Class ;
  rdfs:subClassOf fis:Investor ;
  rdfs:label "shareholder" ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .

fis:Bondholder a owl:Class ;
  rdfs:subClassOf fis:Investor ;
  rdfs:label "bondholder" ;
  rdfs:comment "The creditor to whom the bond issuer owes a debt." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Investor ;
  rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ;
  rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "has underlying" ;
  rdfs:comment "The item (the underlier) upon which a derivative contract is based; may be a commodity, financial instrument, price index, currency or interest rate." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:Derivative .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ;
  rdfs:range fis:Issuer ;
  rdfs:label "has reference entity" ;
  rdfs:comment "The debt issuer whose creditworthiness is referenced by a credit default swap." .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:ConvertibleBond ;
  rdfs:range fis:EquitySecurity ;
  rdfs:label "has conversion target" ;
  rdfs:comment "The class of shares into which a convertible bond may be converted at the election of the holder." .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range fis:Option ;
  rdfs:label "has embedded option" ;
  rdfs:comment "Some bonds contain an embedded option granting option-like features to the holder or issuer, e.g. call or put rights." .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ;
  rdfs:range fis:Dividend ;
  rdfs:label "has dividend" .

fis:isDividendOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ;
  rdfs:range fis:Stock .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "has collateral" ;
  rdfs:comment "Links a debt instrument to the asset(s) pledged as collateral, e.g. a mortgage bond backed by a pool of mortgages." .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:date ;
  rdfs:label "has maturity date" ;
  rdfs:comment "The date on which the principal of a debt security is due to be repaid. Perpetual bonds have no maturity date." .

fis:hasIssueDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:date ;
  rdfs:label "has issue date" .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:decimal ;
  rdfs:label "has face value" ;
  rdfs:comment "The nominal, principal, par, or face amount on which the issuer pays interest and which must usually be repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:label "has coupon rate" ;
  rdfs:comment "The interest rate that the issuer pays to the holder." .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:label "has yield to maturity" .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:string ;
  rdfs:label "has credit rating" .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal ;
  rdfs:label "has strike price" ;
  rdfs:comment "The price at which the sale takes place if the option is exercised, specified when the parties enter into the option." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:date ;
  rdfs:label "has expiration date" .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ;
  rdfs:range xsd:decimal ;
  rdfs:label "has notional amount" ;
  rdfs:comment "The notional principal amount over which swap cash flows are calculated; usually not exchanged between counterparties." .

fis:hasDividendRate a owl:DatatypeProperty ;
  rdfs:domain fis:PreferredStock ;
  rdfs:range xsd:decimal ;
  rdfs:label "has dividend rate" .

fis:hasStandardizedTerms a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:boolean ;
  rdfs:label "has standardized terms" ;
  rdfs:comment "True if the contract terms are standardized and written by a clearing house/exchange (e.g. futures); false if the contract is a non-standardized, privately negotiated agreement (e.g. forwards)." .

#################################################################
# DEBT SECURITY HIERARCHY
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "money market instrument" ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less, generally issued for a period of up to twelve months; highly liquid, sometimes called 'near cash'." .

fis:CommercialPaper a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "commercial paper" ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days, issued at a discount from face value." .

fis:CertificateOfDeposit a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "certificate of deposit" ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term before withdrawal without penalty." .

fis:TreasuryBill a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "treasury bill" ;
  rdfs:comment "A zero-coupon short-term debt obligation of a national government, maturing in one year or less, bought at a discount to par." .

fis:RepurchaseAgreement a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "repurchase agreement" ;
  rdfs:comment "A short-term loan arranged by selling securities to an investor with an agreement to repurchase them at a fixed price on a fixed date. The corpus notes that repurchase agreements 'defy categorization' into the simple cash-instrument/derivative-instrument matrix." .

fis:BankersAcceptance a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "bankers acceptance" .

fis:MunicipalNote a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "municipal note" .

owl:AllDisjointClasses [ owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:TreasuryBill fis:RepurchaseAgreement fis:BankersAcceptance fis:MunicipalNote ) ] .

fis:EuroDebtSecurity a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "euro debt security" ;
  rdfs:comment "A security issued internationally outside its domestic market in a denomination different from that of the issuer's domicile. Includes eurobonds and euronotes." .

fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity ; rdfs:comment "Characteristically underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity .

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to provide cash flow to the holder, usually repayment of principal at maturity plus interest (the coupon) over a specified time." .

fis:Debenture a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "debenture" ;
  rdfs:comment "Conflict in corpus: sometimes used generically as a synonym for any debt security/bond with long maturity (typically at least ten years); elsewhere specifically defined as an unsecured bond. This ontology models Debenture as equivalent to an unsecured Bond (see fis:UnsecuredBond)." .

fis:Note a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "note" ;
  rdfs:comment "A debt security with a shorter maturity than a debenture." .

fis:SecuredBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "secured bond" ; rdfs:comment "Protected by collateral." .
fis:UnsecuredBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "unsecured bond" .
owl:AllDisjointClasses [ owl:members ( fis:SecuredBond fis:UnsecuredBond ) ] .

fis:Debenture owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Bond fis:UnsecuredBond )
] .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "senior bond" ; rdfs:comment "Contractually senior to other unsecured debt; priority in bankruptcy." .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "subordinated bond" ; rdfs:comment "Lower priority than senior bonds in case of liquidation." .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:GovernmentBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "government bond" ;
  rdfs:comment "Also called a sovereign bond or treasury bond (US). Synonym label: 'sovereign bond', 'treasury bond'." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Government ] )
  ] .

fis:MunicipalBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "municipal bond" ;
  rdfs:comment "Issued by a local authority or subdivision within a country; known in the US as a municipal bond ('muni')." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalAuthority ] )
  ] .

fis:GeneralObligationBond a owl:Class ;
  rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer, supported by taxing power." .

fis:RevenueBond a owl:Class ;
  rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Guarantee of repayment solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:AssessmentBond a owl:Class ;
  rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment based on property tax assessments of properties within the issuer's boundaries; a form of general obligation bond." .

fis:SupranationalBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "supranational bond" ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] )
  ] .

fis:CorporateBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "corporate bond" ;
  rdfs:comment "Issued by a corporation to raise financing; strictly excludes bonds of local authorities (municipal bonds), though the term sometimes also encompasses supranational-issued bonds." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ; rdfs:label "investment grade bond" ; rdfs:comment "Rated AAA, AA, A or BBB." .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ; rdfs:label "high-yield bond" ; rdfs:comment "Also called junk bond; rated BB or below." .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ; rdfs:comment "Issued to fund military operations during wartime." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:comment "Raises finance for climate mitigation/adaptation projects." .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet (unlike asset-backed securities)." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:comment "Public sector entities repay private investors after verified improved social outcomes." .

fis:AssetBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "asset-backed security" ;
  rdfs:comment "Corpus notes a terminological conflict: 'asset-backed security' is sometimes an umbrella term for any security backed by a pool of assets (including MBS and CDO as subsets), and sometimes a narrower term distinct from MBS/CDO, referring only to securities backed by consumer loans, leases or receivables other than real estate. This ontology models the umbrella sense, with ConsumerAssetBackedSecurity for the narrower sense." .

fis:ConsumerAssetBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "consumer asset-backed security" ;
  rdfs:comment "Narrower sense of 'ABS': backed by consumer loans, leases or receivables other than real estate, e.g. auto loans, credit cards, student loans." .

fis:HomeEquityLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity .
fis:AutoLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity .
fis:CreditCardAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity .
fis:StudentLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "mortgage-backed security" ;
  rdfs:comment "An asset-backed security secured by a mortgage or pool of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "A pass-through MBS backed by mortgages on single-family, one- to four-unit residential real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "A pass-through MBS backed by mortgages on commercial and multi-family properties." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ;
  rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "collateralized mortgage obligation" ;
  rdfs:comment "Also called a 'pay-through bond'; a debt obligation collateralized by the assets it owns, divided into tranches with different maturities and payment priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "stripped mortgage-backed security" .

fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:comment "Cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:comment "Cash flows backed by the principal repayment component of mortgage payments." .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
  rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "collateralized debt obligation" ;
  rdfs:comment "A structured asset-backed security sliced into tranches catching cash flow in sequence based on seniority." .

fis:ZeroCouponBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "zero-coupon bond" ;
  rdfs:comment "Also called a discount bond or deep discount bond; pays no regular interest and is issued at a substantial discount to par value." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] )
  ] .

fis:FixedRateBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "floating rate note" ;
  rdfs:comment "Coupon varies, linked to a reference rate such as LIBOR/SOFR or Euribor." .

fis:InflationIndexedBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal and interest payments indexed to the level of consumer prices (e.g. TIPS, index-linked gilts)." .

owl:AllDisjointClasses [ owl:members ( fis:ZeroCouponBond fis:FixedRateBond fis:FloatingRateNote fis:InflationIndexedBond ) ] .

fis:PerpetualBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "perpetual bond" ;
  rdfs:comment "Also called a perpetuity or 'Perp'; has no maturity date." .

fis:SerialBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

fis:Methuselah a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond with a maturity of 50 years or longer." .

fis:Option a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "option" ;
  rdfs:comment "A contract which gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ]
    )
  ] .

fis:CallableBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "callable bond" ;
  rdfs:comment "Gives the issuer the right to repay the bond before the maturity date." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] )
  ] .

fis:PutableBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "putable bond" ;
  rdfs:comment "Also called a retractable bond; gives the holder the right to force the issuer to repay before the maturity date." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] )
  ] .

fis:BulletBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
  rdfs:label "convertible bond" ;
  rdfs:comment "A bond that the holder can convert into a specified number of shares of the issuer's common stock or cash of equal value; a hybrid security with debt and equity features." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] )
  ] .

fis:ExchangeableBond a owl:Class ;
  rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:BearerSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "bearer security" ;
  rdfs:comment "Entitles the holder to rights merely by holding the security; transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "registered security" ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register maintained by the issuer or an intermediary." .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:BookEntrySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "A non-certificated security that exists only as an electronic (dematerialized) record." .

fis:CertificatedSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "A security represented by a physical certificate." .

owl:AllDisjointClasses [ owl:members ( fis:BookEntrySecurity fis:CertificatedSecurity ) ] .

fis:DividedSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Each divided security constitutes a separate asset legally distinct from each other security in the same issue." .

fis:UndividedSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset, with each security being a fractional part of this undivided whole." .

owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:BearerBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
  rdfs:comment "An official certificate issued without a named holder; the possessor can claim the value of the bond." .

fis:RegisteredBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
  rdfs:comment "Ownership recorded by the issuer or a transfer agent." .

fis:BookEntryBond a owl:Class ;
  rdfs:subClassOf fis:Bond, fis:BookEntrySecurity ;
  rdfs:comment "A bond without a paper certificate." .

#################################################################
# EQUITY SECURITY HIERARCHY
#################################################################

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "stock" ;
  rdfs:comment "Synonyms: 'share', 'capital stock'. Consists of all the shares by which ownership of a corporation is divided." .

fis:CommonStock a owl:Class ;
  rdfs:subClassOf fis:Stock ;
  rdfs:label "common stock" ;
  rdfs:comment "Synonyms: 'ordinary share', 'voting share'. Typically carries voting rights and lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:label "preferred stock" ;
  rdfs:comment "Synonyms: 'preference shares', 'preferreds'. Senior to common stock and subordinate to bonds in claim; priority in dividends and liquidation over common stock. Generally considered a hybrid instrument combining debt- and equity-like features; legally a capital stock (equity), yet under IAS 32 a mandatorily redeemable preference share would be classified as a financial liability rather than equity, illustrating a conflict between market and accounting classification (see fis:FinancialLiability)." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ;
  rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common dividends resume." .

fis:NoncumulativePreferredStock a owl:Class ;
  rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Also called straight preferred; passed dividends are lost if not declared." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
  rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Includes the ability of the holder to convert the preferred shares into a fixed number of common shares." .

fis:CallablePreferredStock a owl:Class ;
  rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Gives the issuer the right to redeem at a predetermined price." .

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "equity warrant" ;
  rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities." .

fis:Dividend a owl:Class ;
  rdfs:label "dividend" ;
  rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, unlike a bond coupon." .

fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
owl:AllDisjointClasses [ owl:members ( fis:CashDividend fis:StockDividend ) ] .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "depositary receipt" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, traded on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:comment "Issued by European banks." .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# DERIVATIVE HIERARCHY
#################################################################

fis:LockProduct a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "lock product" ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .

fis:OptionProduct a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "option product" ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:LockProduct ;
  rdfs:label "forward" ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today; traded OTC." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasStandardizedTerms ; owl:hasValue "false"^^xsd:boolean ] )
  ] .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:LockProduct ;
  rdfs:label "future" ;
  rdfs:comment "A standardized contract to buy or sell a specified asset of standardized quantity and quality at a price agreed today, with delivery at a specified future date, negotiated at a futures exchange. Note: the Bank for International Settlements instead treats forwards, swaps and options as the three basic derivative types, classifying futures as a standardized (exchange-traded) variety of forward rather than as a sibling category; this ontology follows the four-way market taxonomy (forward, future, option, swap) as the primary classification." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasStandardizedTerms ; owl:hasValue "true"^^xsd:boolean ] )
  ] .

fis:Swap a owl:Class ;
  rdfs:subClassOf fis:LockProduct ;
  rdfs:label "swap" ;
  rdfs:comment "A derivative in which two counterparties exchange cash flows (legs) of one party's financial instrument for those of the other's, over a notional principal amount." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) ] .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .

fis:CreditDefaultSwap a owl:Class ;
  rdfs:subClassOf fis:Swap ;
  rdfs:label "credit default swap" ;
  rdfs:comment "The seller compensates the buyer if a loan default or other credit event occurs on the reference entity; the buyer makes periodic 'spread' payments." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:EquitySwap fis:CommoditySwap fis:CreditDefaultSwap ) ] .

fis:CallOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:label "call option" ;
  rdfs:comment "The right, but not the obligation, to buy an asset at a fixed (strike) price." .

fis:PutOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:label "put option" ;
  rdfs:comment "The right, but not the obligation, to sell an asset at a fixed (strike) price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on the expiration date." .

fis:BermudanOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:BinaryOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option that pays the full amount if the underlying meets a defined condition at expiration." .

fis:ExoticOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "Any option with complex financial structures, e.g. Asian options, barrier options." .

fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:ExoticOption .
fis:AsianOption a owl:Class ; rdfs:subClassOf fis:ExoticOption .

fis:EquityDerivative a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "equity derivative" ;
  rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] )
  ] .

fis:StockOption a owl:Class ;
  rdfs:subClassOf fis:Option, fis:EquityDerivative ;
  rdfs:comment "A class of option whose value changes in reaction to the underlying stock." .

fis:StockFuture a owl:Class ;
  rdfs:subClassOf fis:Future, fis:EquityDerivative ;
  rdfs:comment "A cash-settled futures contract on the value of a particular stock or stock market index." .

fis:InterestRateDerivative a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:CurrencyDerivative a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:CommodityDerivative a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:CreditDerivative a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Transfers credit risk from a protection buyer to a protection seller, e.g. credit default swaps." .

#################################################################
# FUNDS
#################################################################

fis:InvestmentFund a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "investment fund" ;
  rdfs:comment "An investment fund that pools money from many investors to purchase securities; its value is derived from the portfolio of underlying securities it holds." .

fis:MutualFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "mutual fund" ;
  rdfs:comment "An SEC-registered open-end investment company that pools money from investors; shares transact at next-calculated net asset value (NAV)." .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:comment "Invests in liquid, short-term debt securities." .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:comment "Also called income fund; invests primarily in bonds." .
fis:StockFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:comment "Also called equity fund; invests primarily in stocks." .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:comment "Invests in a combination of asset classes." .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "A passively managed fund that tracks the performance of an index." .

fis:ActivelyManagedFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Seeks to outperform market indices through active security selection; generally charges higher fees." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:ExchangeTradedFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "exchange-traded fund" ;
  rdfs:comment "Pools investor money like a mutual fund, but shares trade on national securities exchanges at market prices that may be at a premium or discount to net asset value." .

fis:IndexExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund, fis:IndexFund .
fis:ActivelyManagedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund, fis:ActivelyManagedFund .
fis:InverseExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ; rdfs:comment "Designed to move opposite to its benchmark." .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ; rdfs:comment "Seeks to amplify the benchmark's daily return." .

fis:HedgeFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "hedge fund" ;
  rdfs:comment "Pools money from investors like a mutual fund but is subject to fewer protective regulations and uses more flexible, risky strategies; available only to high-net-worth/institutional investors." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

#################################################################
# ACCOUNTING CLASSIFICATION (IAS 32 / IFRS 9)
#################################################################

fis:FinancialAsset a owl:Class ;
  rdfs:label "financial asset (accounting)" ;
  rdfs:comment "Per IAS 32: cash; an equity instrument of another entity; a contractual right to receive cash or another financial asset; or a contractual right to exchange financial assets/liabilities under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:label "financial liability (accounting)" ;
  rdfs:comment "Per IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial assets/liabilities under potentially unfavourable conditions. A mandatorily redeemable preference share is classified here, even though it is commonly described in markets as preferred equity -- a documented conflict with the market taxonomy's fis:PreferredStock (subclass of fis:EquitySecurity)." .

fis:AccountingEquityInstrument a owl:Class ;
  rdfs:label "equity instrument (accounting)" ;
  rdfs:comment "Per IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. Classification depends on the absence of a contractual obligation to deliver cash, not on the instrument's legal name." .

fis:AmortizedCostFinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "Per IFRS 9: held in a 'hold to collect' business model and passes the solely-payments-of-principal-and-interest (SPPI) test." .

fis:FairValueOCIFinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "Per IFRS 9: held in a 'hold to collect and sell' business model and passes the SPPI test." .

fis:FairValueProfitOrLossFinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "Per IFRS 9: all other financial assets, including derivatives and equity investments (unless the OCI election is made)." .

owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostFinancialAsset fis:FairValueOCIFinancialAsset fis:FairValueProfitOrLossFinancialAsset ) ] .

#################################################################
# SECURITY FORM / COLLATERAL (misc)
#################################################################

fis:FungibleSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .

fis:NonFungibleSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Not fungible with other securities, e.g. different series of bonds issued by the same company with different conditions." .

owl:AllDisjointClasses [ owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) ] .
