```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An OWL ontology modelling securities, debt, equity, hybrid and derivative financial instruments, investment funds and their defining attributes, built strictly from the supplied corpus." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled. IAS 32/39 define it as any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity. Financial instruments are either cash instruments or derivative instruments." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "An instrument whose value is determined directly by the markets; includes securities (readily transferable) and instruments such as loans and deposits, where both borrower and lender must agree to a transfer." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" , "derivative instrument" ;
  rdfs:comment "A contract between a buyer and seller whose value is derived from an underlier (commodity, financial instrument, price index, currency or interest rate). Note: the US SEC definition treats derivatives as one category of 'security' alongside debt and equity securities, while other sources (ECB, BIS, IAS 32) treat derivatives as a category of financial instrument distinct from securities; this ontology follows the latter, majority structural framing and records the conflict here." .

fis:InvestmentFund a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "investment fund" ;
  rdfs:comment "An investment vehicle that pools money from many investors to purchase securities; shares of the fund are issued to investors." .

fis:FinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial asset" ;
  rdfs:comment "Per IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial assets/liabilities under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial liability" ;
  rdfs:comment "Per IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial assets/liabilities under potentially unfavourable conditions." .

fis:Underlier a owl:Class ;
  rdfs:label "underlier" ;
  rdfs:comment "The item upon which a derivative's value depends: can or must be bought or sold; can be a commodity, a financial instrument (e.g. a stock or bond), a price index, a currency, or an interest rate." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "commodity" .
fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "market index" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "currency" .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "interest rate" .

fis:DebtObligation a owl:Class ;
  rdfs:subClassOf fis:Underlier ;
  rdfs:label "debt obligation" ;
  rdfs:comment "A generic class of loans or debt securities, used e.g. as the underlying of a collateralized debt obligation." .

fis:Loan a owl:Class ;
  rdfs:subClassOf fis:CashInstrument , fis:DebtObligation ;
  rdfs:label "loan" ;
  rdfs:comment "A cash instrument requiring agreement between borrower and lender for transfer; not readily transferable like a security." .

fis:Deposit a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "deposit" .

fis:Mortgage a owl:Class ;
  rdfs:subClassOf fis:Loan ;
  rdfs:label "mortgage" .

fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "residential mortgage" .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "commercial mortgage" .

fis:Dividend a owl:Class ;
  rdfs:label "dividend" ;
  rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, unlike the contractual coupon of a debt security." .

#################################################################
# ISSUER CLASSES
#################################################################

fis:Issuer a owl:Class ;
  rdfs:label "issuer" ;
  rdfs:comment "The company or other entity issuing the security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "corporation" .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Corporation ; rdfs:label "bank" .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "sovereign government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "local government" ;
  rdfs:comment "A state, provincial, territorial, municipal or other governmental unit other than a sovereign government." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "supranational organization" .

#################################################################
# MEASUREMENT CATEGORY (IFRS 9 classification overlay)
#################################################################

fis:MeasurementCategory a owl:Class ; rdfs:label "measurement category" .
fis:AmortizedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "amortised cost" .
fis:FairValueThroughOtherComprehensiveIncomeMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "fair value through OCI" .
fis:FairValueThroughProfitOrLossMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "fair value through profit or loss" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmortizedCostMeasurement fis:FairValueThroughOtherComprehensiveIncomeMeasurement fis:FairValueThroughProfitOrLossMeasurement ) .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security ;
  rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Underlier ;
  rdfs:label "has underlying" .

fis:hasConversionTarget a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:HybridSecurity ; rdfs:range fis:EquitySecurity ;
  rdfs:label "has conversion target" .

fis:hasPortfolioHolding a owl:ObjectProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range fis:Security ;
  rdfs:label "has portfolio holding" .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ; rdfs:range fis:Dividend ;
  rdfs:label "has dividend" .

fis:hasMeasurementCategory a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:MeasurementCategory ;
  rdfs:label "has measurement category" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ; rdfs:label "has maturity date" .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ; rdfs:label "has coupon rate" .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ; rdfs:label "has face value" .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ; rdfs:label "has credit rating" .

fis:hasCollateral a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean ; rdfs:label "has collateral" .

fis:hasBalanceSheetTreatment a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
  rdfs:label "has balance sheet treatment" ;
  rdfs:comment "True if underlying assets remain on the issuer's balance sheet (covered bond); false if transferred off balance sheet (asset-backed security)." .

fis:hasSeniorityLevel a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string ; rdfs:label "has seniority level" ;
  rdfs:comment "Value 'senior' or 'subordinated'." .

fis:hasCallability a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ; rdfs:label "has callability" .

fis:hasPutability a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ; rdfs:label "has putability" .

fis:hasPurpose a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string ; rdfs:label "has purpose" .

fis:hasVotingRight a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean ; rdfs:label "has voting right" .

fis:hasCumulativeFeature a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:PreferredStock ; rdfs:range xsd:boolean ; rdfs:label "has cumulative feature" .

fis:hasTransferability a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:CashInstrument ; rdfs:range xsd:boolean ; rdfs:label "has transferability" .

fis:hasCertificateForm a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string ; rdfs:label "has certificate form" ;
  rdfs:comment "Value 'bearer', 'registered' or 'bookEntry'." .

fis:hasDivisibility a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string ; rdfs:label "has divisibility" ;
  rdfs:comment "Value 'divided' or 'undivided'." .

fis:hasFungibility a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ; rdfs:label "has fungibility" .

fis:hasStandardization a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:boolean ; rdfs:label "has standardization" .

fis:hasSettlementObligation a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:string ; rdfs:label "has settlement obligation" ;
  rdfs:comment "Value 'mandatory' (lock products: forwards, futures, swaps) or 'optional' (option products)." .

fis:hasOptionRight a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ; rdfs:label "has option right" ;
  rdfs:comment "Value 'buy' (call) or 'sell' (put)." .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ; rdfs:label "has exercise style" ;
  rdfs:comment "Value 'American', 'European' or 'Bermudan'." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ; rdfs:label "has strike price" .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ; rdfs:label "has premium" .

fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal ; rdfs:label "has notional amount" .

fis:hasIssuanceRegion a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DepositaryReceipt ; rdfs:range xsd:string ; rdfs:label "has issuance region" .

fis:hasCashFlowComponent a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:StrippedMortgageBackedSecurity ; rdfs:range xsd:string ; rdfs:label "has cash flow component" ;
  rdfs:comment "Value 'interest' or 'principal'." .

fis:hasTradingVenue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range xsd:string ; rdfs:label "has trading venue" ;
  rdfs:comment "Value 'exchange' (ETF) or 'issuer' (mutual fund, transacted at NAV)." .

fis:hasRegulatoryStatus a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range xsd:boolean ; rdfs:label "has regulatory status" .

#################################################################
# SECURITY (top of tradable-instrument hierarchy)
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:CashInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasTransferability ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset. The corpus offers several, partly conflicting definitions (e.g. 'any tradable financial asset', 'a financial contract entitling the holder to investment returns', jurisdiction-specific legal definitions excluding or including warrants). This ontology follows the majority Wikipedia/US framing: a security is a readily transferable cash instrument." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Security fis:Loan fis:Deposit ) .

### Cross-cutting Security dimensions (certificate form, divisibility, fungibility)

fis:BearerSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "bearer" ] ) ] ;
  rdfs:label "bearer security" ;
  rdfs:comment "Entitles the holder to rights merely by holding the instrument; transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "registered" ] ) ] ;
  rdfs:label "registered security" ;
  rdfs:comment "Entitles the holder to rights only if recorded on a security register." .

fis:NonCertificatedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "bookEntry" ] ) ] ;
  rdfs:label "non-certificated security" ;
  rdfs:comment "Electronic / dematerialised / book-entry-only form." .

[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:NonCertificatedSecurity ) .

fis:DividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "divided" ] ) ] ;
  rdfs:label "divided security" .

fis:UndividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "undivided" ] ) ] ;
  rdfs:label "undivided security" .

[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue true ] ) ] ;
  rdfs:label "fungible security" ;
  rdfs:comment "All holdings are treated identically and are interchangeable." .

#################################################################
# TOP SECURITY FAMILIES: DEBT, EQUITY, HYBRID
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security , fis:DebtObligation ;
  rdfs:label "debt security" ;
  rdfs:comment "A negotiable financial instrument evidencing a promise by the issuer to make payment(s) to the holder on specified future date(s), typically principal plus interest (coupon). Called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; a residual claim after creditors have been paid, carrying pro-rata control and participation in profits." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preference shares, convertibles, equity warrants)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) .

#################################################################
# BOND HIERARCHY
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "An instrument of indebtedness under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon) over time." .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "money market instrument" ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less; highly liquid, sometimes called 'near cash'." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Bond fis:MoneyMarketInstrument ) .

### Bond classified by nature of issuer

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "government bond" , "sovereign bond" , "treasury bond" ;
  rdfs:comment "Medium or long term debt security issued by a sovereign government or its agencies." .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:label "municipal bond" ;
  rdfs:comment "Issued by a local authority or subdivision within a country (state, city, county, town)." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "supranational bond" .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:label "corporate bond" ;
  rdfs:comment "Issued by a corporation to raise financing for operations, M&A or expansion." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "general obligation bond" ;
  rdfs:comment "Secured by the full faith, credit and taxing power of the issuer; usually requires voter approval." .

fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "revenue bond" ;
  rdfs:comment "Repaid solely from revenues generated by a specified revenue-generating project; typically non-recourse." .

[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:label "assessment bond" ;
  rdfs:comment "Repayment based on property tax assessments; a form of general obligation bond." .

fis:WarBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:GovernmentBond
    [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "militaryFunding" ] ) ] ;
  rdfs:label "war bond" .

fis:ClimateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "climateChangeMitigation" ] ) ] ;
  rdfs:label "climate bond" , "green bond" .

fis:SocialImpactBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "socialOutcome" ] ) ] ;
  rdfs:label "social impact bond" .

### Bond classified by credit quality (corporate)

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:label "investment grade bond" , "high grade bond" ;
  rdfs:comment "Rated AAA, AA, A or BBB." .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:label "high yield bond" , "junk bond" ;
  rdfs:comment "Rated below investment grade (BB and below); higher default risk, higher yield." .

[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

### Bond classified by collateral / seniority

fis:SecuredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue true ] ) ] ;
  rdfs:label "secured bond" .

fis:Debenture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] ;
  rdfs:label "debenture" ;
  rdfs:comment "An unsecured bond, having only a general claim on the issuer's assets and cash flows." .

[] a owl:AllDisjointClasses ; owl:members ( fis:SecuredBond fis:Debenture ) .

fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniorityLevel ; owl:hasValue "senior" ] ) ] ;
  rdfs:label "senior bond" .

fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniorityLevel ; owl:hasValue "subordinated" ] ) ] ;
  rdfs:label "subordinated bond" ;
  rdfs:comment "Lower priority than senior bonds of the issuer in liquidation; usually carries a lower credit rating." .

[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

### Bond classified by embedded option

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCallability ; owl:hasValue true ] ) ] ;
  rdfs:label "callable bond" ;
  rdfs:comment "Gives the issuer the right to repay the bond before maturity on call dates." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasPutability ; owl:hasValue true ] ) ] ;
  rdfs:label "putable bond" , "retractable bond" ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity." .

### Bond classified by coupon structure

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "zero-coupon bond" , "discount bond" ;
  rdfs:comment "Pays no periodic interest; issued at a substantial discount to par, with the full principal paid at redemption." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "fixed rate bond" ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "floating rate note" ;
  rdfs:comment "Coupon varies, linked to a money market reference rate (e.g. SOFR, historically LIBOR)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:ZeroCouponBond fis:FixedRateBond fis:FloatingRateNote ) .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "perpetual bond" , "perpetuity" ;
  rdfs:comment "Has no maturity date; principal is repaid only at the discretion of the issuer, if ever." .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "serial bond" ;
  rdfs:comment "Matures in installments over a period of time." .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "inflation-indexed bond" , "inflation-linked bond" ;
  rdfs:comment "Principal amount and interest payments are indexed to the level of consumer prices." .

### Bond classified by certificate form (cross-cutting with Security)

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
  rdfs:label "bearer bond" .

fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
  rdfs:label "registered bond" .

fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] ;
  rdfs:label "book-entry bond" .

### Mortgage / asset backed bonds

fis:MortgageBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:SecuredBond
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "mortgage bond" ;
  rdfs:comment "A bond backed by a pool of mortgages on real estate, or more generally secured by the pledge of specific assets." .

fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Loan ]
    [ a owl:Restriction ; owl:onProperty fis:hasBalanceSheetTreatment ; owl:hasValue false ] ) ] ;
  rdfs:label "asset-backed security" ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from pooled assets (loans, leases, receivables), transferred off the issuer's balance sheet; contrasted with covered bonds, where assets remain on balance sheet." .

fis:CoveredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ]
    [ a owl:Restriction ; owl:onProperty fis:hasBalanceSheetTreatment ; owl:hasValue true ] ) ] ;
  rdfs:label "covered bond" ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets, which remain on the issuer's balance sheet (unlike asset-backed securities)." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "mortgage-backed security" .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:label "collateralized debt obligation" ;
  rdfs:comment "Asset-backed security backed by a pool of debt obligations (often other asset-backed securities)." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:label "residential mortgage-backed security" .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:label "commercial mortgage-backed security" .

[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "collateralized mortgage obligation" , "pay-through bond" ;
  rdfs:comment "Divided into tranches with different maturities and priorities for receipt of principal." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "stripped mortgage-backed security" ;
  rdfs:comment "Each mortgage payment's interest and principal components are separated into distinct securities." .

fis:InterestOnlyStrip a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCashFlowComponent ; owl:hasValue "interest" ] ) ] ;
  rdfs:label "interest-only strip" .

fis:PrincipalOnlyStrip a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCashFlowComponent ; owl:hasValue "principal" ] ) ] ;
  rdfs:label "principal-only strip" .

[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:CommercialPaper a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] ;
  rdfs:label "commercial paper" ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "certificate of deposit" ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term." .

fis:TreasuryBill a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "treasury bill" ;
  rdfs:comment "Zero-coupon government debt obligation maturing in one year or less." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ; rdfs:label "banker's acceptance" .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "repurchase agreement" ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:TreasuryBill fis:BankersAcceptance fis:RepurchaseAgreement ) .

#################################################################
# EQUITY HIERARCHY
#################################################################

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "stock" , "share" ;
  rdfs:comment "A unit of fractional ownership of a corporation, entitling the holder to a share of earnings, liquidation proceeds and/or voting power." .

fis:CommonStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] ;
  rdfs:label "common stock" , "ordinary share" ;
  rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ] ) ] ;
  rdfs:label "preferred stock" , "preference share" ;
  rdfs:comment "Typically does not carry voting rights but has priority over common stock for dividends and liquidation proceeds; a hybrid instrument combining debt-like and equity-like features." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasCumulativeFeature ; owl:hasValue true ] ) ] ;
  rdfs:label "cumulative preferred stock" ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common dividends resume." .

fis:NoncumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasCumulativeFeature ; owl:hasValue false ] ) ] ;
  rdfs:label "noncumulative preferred stock" , "straight preferred stock" ;
  rdfs:comment "Missed dividends are simply lost, not carried forward." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:label "convertible preferred stock" ;
  rdfs:comment "Preferred stock that can be converted into a fixed number of common shares." .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:label "depositary receipt" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded shares, enabling local trading without the shares leaving their home country." .

fis:AmericanDepositaryReceipt a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DepositaryReceipt
    [ a owl:Restriction ; owl:onProperty fis:hasIssuanceRegion ; owl:hasValue "US" ] ) ] ;
